R=/scratch/jjyeung/orch_n30
w=sb_ktrev2; mkdir -p $R/$w/out; cp $R/sb_cursor_probe/AGENTS.md $R/$w/AGENTS.md; echo  | base64 -d > $R/$w/PROMPT.md
cd $R/$w && tmux new-session -d -s $w "OMP_NUM_THREADS=8 MKL_NUM_THREADS=8 OPENBLAS_NUM_THREADS=8 nice -n 10 timeout 5400 agent -p -f --sandbox disabled --trust --model claude-opus-5-5-xhigh 'Read PROMPT.md in this folder and carry out the task it describes, completely.' > cursor.log 2>&1"
sleep 2; tmux ls -F "#{session_name}" | grep "^sb_" | tr "\n" " "; echo; free -g | sed -n 2p; cat /proc/loadavg
